min="0.1" :max="0.4" :step="0.05" :precision="2" style="width:100%" /><div class="field-help">按时间顺序留出的后段数据比例；默认 0.20。</div></el-col></el-row></el-card><el-card v-if="form.enabled_methods.includes('rolling_validation')" shadow="never" class="algorithm-card"><template #header>时间顺序滚动验证</template><div class="setting-label">验证窗口数量</div><el-input-number v-model="form.rolling_folds" :min="2" :max="5" :step="1" style="width:260px" /><div class="field-help">在不同时间位置重复前段训练、后段测试；默认 3 次。</div></el-card></div></div></el-form-item>
