    <el-card shadow="never" class="history-card"><template #header><div class="header"><span>时间段影响分析记录</span><span>{{ history.length }} 条</span></div></template><el-table :data="history" stripe v-loading="historyLoading" empty-text="暂无时间段影响分析记录"><el-table-column prop="id" label="记录 ID" width="100"/><el-table-column prop="name" label="分析名称" min-width="220" show-overflow-tooltip/><el-table-column label="数据集" min-width="220"><template #default="{row}">#{{ row.dataset_id }} {{ row.dataset_name }}</template></el-table-column><el-table-column label="时间范围" min-width="250"><template #default="{row}">{{ configOf(row).start_time || '-' }} 至 {{ configOf(row).end_time || '-' }}</template></el-table-column><el-table-column prop="created_at" label="创建时间" min-width="180"><template #default="{row}">{{ formatDate(row.created_at) }}</template></el-table-column><el-table-column label="操作" width="160" fixed="right"><template #default="{row}"><el-button link type="primary" :loading="openingRunId===row.id" @click="openRun(row.id)">查看</el-button><el-button v-if="userStore.hasPermission('datasets:analyze')" link type="danger" @click="removeRun(row)">删除</el-button></template></el-table-column></el-table></el-card>

    <el-dialog v-model="explanationVisible" title="指标说明" width="860px"><el-table :data="metricExplanations" stripe max-height="560"><el-table-column prop="name" label="指标" width="170"/><el-table-column prop="meaning" label="含义与作用" min-width="420"/><el-table-column prop="interpretation" label="如何理解" min-width="220"/></el-table></el-dialog>
    <el-dialog v-model="algorithmExplanationVisible" title="过程影响分析：分析流程说明" width="900px"><el-alert type="warning" :closable="false" title="本功能用于对比所选时间段内各变量的统计影响证据，不会直接证明物理因果，也不会自动生成控制指令。" style="margin-bottom:14px"/><el-table :data="algorithmExplanations" stripe max-height="560"><el-table-column prop="name" label="方法" width="190"/><el-table-column prop="purpose" label="在本功能中的作用" min-width="300"/><el-table-column prop="process" label="具体做法" min-width="330"/><el-table-column prop="read" label="算法作用" min-width="260"/></el-table></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import * as echarts from 'echarts'
import PageHeader from '@/components/PageHeader.vue'
import { useUserStore } from '@/stores/user'
import { del, get, post } from '@/api/legacy'
const userStore = useUserStore()
const datasets = ref<any[]>([]), columns = ref<any>({ columns: [], numeric_columns: [], row_count: 0 }), history = ref<any[]>([])
const historyLoading = ref(false), current = ref<any>(null), running = ref(false), progress = ref(0), openingRunId = ref<number | null>(null), aiLoading = ref(false), aiResult = ref<any>(null), aiQuestion = ref(''), explanationVisible = ref(false), algorithmExplanationVisible = ref(false)
const timelineChartEl = ref<HTMLElement>(), timelineLoading = ref(false), timeline = ref<any>({ timestamps: [], range_starts: [], range_ends: [], series: {}, returned_rows: 0, source_rows: 0, sampled: false })
let timelineChart: echarts.ECharts | null = null
let progressTimer: number | undefined
let timelineRangeTimer: number | undefined
let timelineRequestId = 0
const form = ref<any>({ name: '时间段过程影响分析', dataset_id: null, time_column: null, time_range: [], target_columns: [], candidate_columns: [], enabled_methods: ['lag_correlation', 'conditional_permutation', 'rolling_validation'], max_lag: 24, resample_interval_seconds: 0, interpolation_limit: 3, ridge_alpha: 1, holdout_ratio: 0.2, rolling_folds: 3 })
const result = computed<any>(() => current.value?.result || {}), impact = computed<any>(() => result.value?.analyses?.period_impact_attribution || {})
const availableCandidates = computed(() => columns.value.numeric_columns.filter((column: string) => !form.value.target_columns.includes(column)))
const previewColumns = computed<string[]>(() => { const selected = [...new Set([...form.value.target_columns, ...form.value.candidate_columns])]; return (selected.length ? selected : columns.value.numeric_columns).slice(0, 6) })
const metricExplanations = [
  { name: '最佳领先(秒)', meaning: '在所选最大滞后范围内，自变量变化与因变量变化关联最强的领先时间。', interpretation: '正值表示自变量变化在前；只是时间先后，不是因果证明。' },
  { name: '滞后相关', meaning: '自变量变化量与其后因变量变化量的线性相关程度。', interpretation: '正数偏同向、负数偏反向；绝对值越大关联越明显。' },
  { name: '独立 R²损失', meaning: '保留因变量历史和其他所选自变量后，单独打乱该变量使后段预测 R² 降低多少。', interpretation: '越大说明该变量提供的独立统计信息越多。' },
  { name: 'MAE 增加', meaning: '打乱该变量后，平均绝对预测误差增加的幅度。', interpretation: '大于 0 表示模型失去该变量后预测变差。' },
  { name: '模型统计方向', meaning: '在控制其他所选变量后，模型中最强滞后项的正负关系。', interpretation: '不是建议调节方向，也不等于物理因果方向。' },
  { name: '后段测试 R²', meaning: '用前段时间数据拟合，在后段未参与拟合的数据上测试的解释/预测程度。', interpretation: '接近 1 较好；0 表示不优于均值；负值表示较差。' },
  { name: '自变量增量 R²', meaning: '加入全部所选自变量后，相比只用因变量自身历史，R² 增加多少。', interpretation: '越大说明自变量组整体提供更多附加信息。' },
  { name: '滚动 R²均值 / 最低值', meaning: '在多个按时间顺序移动的测试窗口中重复验证模型。', interpretation: '均值较高且最低值不过低，说明该时间段内关系更稳定。' },
  { name: '证据等级', meaning: '综合独立 R²损失和滞后变化关系得到的排查优先级。', interpretation: '仅表示统计证据强弱，不代表已确认根因。' },
]
const algorithmExplanations = [
  { name: '基础步骤：时间对齐与重采样', purpose: '把不同时间记录的数据排到同一条时间线上。', process: '系统按统一时间间隔整理记录；只补很短的空缺，不会凭空补出长段数据。', read: '这是全部分析的前提，保证后面的比较是在“同一时刻”的数据之间进行。' },
  { name: '差分滞后互相关分析', purpose: '查看某项操作变化后，目标指标会不会跟着变化，以及大约晚多少秒。', process: '系统比较各字段每一刻的增减，并在设定范围内寻找最明显的先后关系。', read: '帮助判断“谁先动、谁后动”和变化方向；它只是辅助线索，不单独决定排名。' },
  { name: '岭回归与分组置换重要性', purpose: '给自变量排影响力名次，是本功能最主要的排名方法。', process: '先把目标历史和全部已选操作一起放进岭回归模型；再一次只打乱一个变量，检查预测结果变差多少。', read: '打乱后结果变差越明显，说明该变量在这一时间段内的独立统计影响越强，排名越靠前。' },
  { name: '时间序列滚动起点验证', purpose: '检查排出来的影响力是否只是在某一小段时间里碰巧成立。', process: '系统换多个时间窗口，重复用前段数据学习、用后段数据检查。', read: '多段时间都得到相近结果，说明这份影响力排名更稳定、更值得现场优先核查。' },
]
function configOf(row: any) { return row?.configuration && typeof row.configuration === 'object' ? row.configuration : {} }
function isPeriodRun(row: any) { return Array.isArray(configOf(row).analyses) && configOf(row).analyses.includes('period_impact_attribution') }
function evidenceTagType(level: string) { return level === '较强统计证据' ? 'success' : level === '中等统计证据' ? 'warning' : level === '较弱统计证据' ? 'info' : 'danger' }
function formatDate(value: string) { return value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '-' }
function normalizeTimelineValue(value: any, edge: 'start' | 'end' = 'end') { const timestamps = timeline.value.timestamps || []; const index = typeof value === 'number' ? Math.max(0, Math.min(timestamps.length - 1, Math.round(value))) : timestamps.indexOf(String(value || '')); if (index < 0) return String(value || ''); const ranges = edge === 'start' ? timeline.value.range_starts : timeline.value.range_ends; return ranges?.[index] || timestamps[index] || '' }
function applyTimelineRange(start: any, end: any) { const begin = normalizeTimelineValue(start, 'start'), finish = normalizeTimelineValue(end, 'end'); if (begin && finish) form.value.time_range = begin <= finish ? [begin, finish] : [finish, begin] }
function scheduleTimelineRange(start: any, end: any) { if (timelineRangeTimer) window.clearTimeout(timelineRangeTimer); timelineRangeTimer = window.setTimeout(() => applyTimelineRange(start, end), 140) }
function renderTimeline() {
  if (!timelineChartEl.value || !timeline.value.timestamps?.length) return
  if (!timelineChart) timelineChart = echarts.init(timelineChartEl.value, undefined, { renderer: 'canvas', useDirtyRect: true })
  const timestamps = timeline.value.timestamps
  timelineChart.off('datazoom'); timelineChart.off('brushSelected')
  timelineChart.setOption({
    animation: false,
    tooltip: { trigger: 'axis', transitionDuration: 0, axisPointer: { animation: false } },
    legend: { type: 'scroll', top: 4 }, grid: { left: 64, right: 30, top: 42, bottom: 92 },
    toolbox: { right: 12, feature: { brush: { type: ['lineX', 'clear'] }, dataZoom: { yAxisIndex: 'none' }, restore: {} } },
    brush: { xAxisIndex: 'all', brushMode: 'single' },
    xAxis: { type: 'category', boundaryGap: false, data: timestamps, axisLabel: { formatter: (value: string) => value.slice(5, 19), hideOverlap: true } },
    yAxis: { type: 'value', scale: true },
    dataZoom: [{ type: 'slider', height: 22, bottom: 26, start: 0, end: 100, throttle: 120 }, { type: 'inside', throttle: 120 }],
    series: Object.entries(timeline.value.series || {}).map(([name, values]) => ({ name, type: 'line', showSymbol: false, sampling: 'lttb', large: true, largeThreshold: 1000, progressive: 4000, progressiveThreshold: 3000, data: values as any[] }))
  }, { notMerge: true, lazyUpdate: true })
  timelineChart.on('datazoom', (event: any) => { const item = event.batch?.[0] || event; const start = item.startValue ?? Math.round(((item.start ?? 0) / 100) * (timestamps.length - 1)); const end = item.endValue ?? Math.round(((item.end ?? 100) / 100) * (timestamps.length - 1)); scheduleTimelineRange(start, end) })
  timelineChart.on('brushSelected', (event: any) => { const area = event.batch?.[0]?.areas?.[0]; if (area?.coordRange?.length === 2) applyTimelineRange(area.coordRange[0], area.coordRange[1]) })
}
async function loadTimeline(retry = true) {
  if (!form.value.dataset_id || !form.value.time_column) return
  const requestId = ++timelineRequestId; timelineLoading.value = true
  try {
    const loaded = await get(`/data-analysis/datasets/${form.value.dataset_id}/timeline`, { time_column: form.value.time_column, columns: previewColumns.value.join(','), max_points: 2400 }, { normalizeTime: false })
    if (requestId !== timelineRequestId) return
    timeline.value = loaded; await nextTick(); renderTimeline()
  } catch (error: any) {
    if (requestId !== timelineRequestId) return
    if (retry && /failed to fetch|networkerror/i.test(String(error?.message || error))) { window.setTimeout(() => loadTimeline(false), 700); return }
    ElMessage.error(error?.message || '时间轴加载失败，请稍后刷新时间轴')
  } finally { if (requestId === timelineRequestId) timelineLoading.value = false }
}
function resizeTimeline(){timelineChart?.resize()}
function startProgress() { progress.value = 5; progressTimer = window.setInterval(() => { if (progress.value < 92) progress.value += Math.max(1, Math.round((94 - progress.value) / 10)) }, 500) }
function stopProgress() { if (progressTimer) window.clearInterval(progressTimer); progress.value = 100; window.setTimeout(() => { progress.value = 0 }, 500) }
async function loadColumns(id: number, retry = true) { columns.value = { columns: [], numeric_columns: [], row_count: 0 }; timeline.value={timestamps:[],range_starts:[],range_ends:[],series:{},returned_rows:0,source_rows:0,sampled:false}; form.value.time_column = null; form.value.target_columns = []; form.value.candidate_columns = []; form.value.time_range = []; if (!id) return; try { columns.value = await get(`/data-analysis/datasets/${id}/columns`); form.value.time_column = columns.value.detected_time_column || null } catch (error: any) { if (retry && /failed to fetch|networkerror/i.test(String(error?.message || error))) { window.setTimeout(() => loadColumns(id, false), 700); return }; ElMessage.error(error?.message || '字段加载失败，请重新选择数据集') } }
async function loadHistory() { historyLoading.value = true; try { const response = await get('/data-analysis/runs'); history.value = (response.items || []).filter(isPeriodRun) } catch (error: any) { ElMessage.error(error?.message || '历史记录加载失败') } finally { historyLoading.value = false } }
async function bootstrap() { try { const response = await get('/datasets'); datasets.value = (response.items || response || []).filter((item: any) => item.has_file) } catch (error: any) { ElMessage.error(error?.message || '数据集加载失败') }; await loadHistory() }
async function runAnalysis() { if (!form.value.dataset_id) return ElMessage.warning('请选择数据集'); if (!form.value.time_column) return ElMessage.warning('请选择时间变量'); const [start_time, end_time] = form.value.time_range || []; if (!start_time || !end_time) return ElMessage.warning('请选择完整分析时间段'); if (!form.value.target_columns.length) return ElMessage.warning('请选择至少一个因变量'); if (!form.value.candidate_columns.length) return ElMessage.warning('请选择至少一个自变量'); if (!form.value.enabled_methods.length) return ElMessage.warning('请至少选择一种分析算法'); if (form.value.target_columns.length > 8 || form.value.candidate_columns.length > 12) return ElMessage.warning('因变量最多 8 个，自变量最多 12 个'); running.value = true; startProgress(); try { const params = { target_columns: [...form.value.target_columns], candidate_columns: [...form.value.candidate_columns], enabled_methods: [...form.value.enabled_methods], max_lag: form.value.max_lag, resample_interval_seconds: form.value.resample_interval_seconds, interpolation_limit: form.value.interpolation_limit, ridge_alpha: form.value.ridge_alpha, holdout_ratio: form.value.holdout_ratio, rolling_folds: form.value.rolling_folds }; const payload = { name: form.value.name || '时间段过程影响分析', dataset_id: form.value.dataset_id, analyses: ['period_impact_attribution'], time_column: form.value.time_column, target_column: form.value.target_columns[0], numeric_columns: [...new Set([...form.value.target_columns, ...form.value.candidate_columns])], algorithm_params: { period_impact_attribution: params }, start_time, end_time }; const response = await post('/data-analysis/runs', payload); current.value = { ...response, configuration: payload }; aiResult.value = null; await loadHistory(); ElMessage.success('时间段过程影响分析已完成并保存'); window.scrollTo({ top: 360, behavior: 'smooth' }) } catch (error: any) { ElMessage.error(error?.message || '影响分析失败') } finally { running.value = false; stopProgress() } }
async function openRun(id: number) { openingRunId.value = id; try { current.value = await get(`/data-analysis/runs/${id}`); aiResult.value = null; window.scrollTo({ top: 360, behavior: 'smooth' }) } catch (error: any) { ElMessage.error(error?.message || '记录加载失败') } finally { openingRunId.value = null } }
async function explainWithAi() { if (!current.value?.id) return ElMessage.warning('请先运行或打开一条分析记录'); aiLoading.value = true; try { aiResult.value = await post(`/data-analysis/runs/${current.value.id}/period-impact-ai`, { question: aiQuestion.value.trim() }); if (aiResult.value?.available) ElMessage.success('AI 综合解读已生成'); else ElMessage.warning(aiResult.value?.warning || 'AI 解读暂不可用') } catch (error: any) { ElMessage.error(error?.message || 'AI 解读请求失败') } finally { aiLoading.value = false } }
async function removeRun(row: any) { try { await ElMessageBox.confirm(`确定删除时间段影响分析记录 #${row.id} 吗？`, '删除记录', { type: 'warning' }); await del(`/data-analysis/runs/${row.id}`); if (current.value?.id === row.id) current.value = null; await loadHistory(); ElMessage.success('已删除') } catch (error: any) { if (error !== 'cancel') ElMessage.error(error?.message || '删除失败') } }
function downloadReport() { if (!current.value) return; const blob = new Blob([JSON.stringify(current.value, null, 2)], { type: 'application/json;charset=utf-8' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `period_impact_${current.value.id}.json`; anchor.click(); URL.revokeObjectURL(url) }
onMounted(() => { bootstrap(); window.addEventListener('resize', resizeTimeline) })
onBeforeUnmount(() => { if (progressTimer) window.clearInterval(progressTimer); if (timelineRangeTimer) window.clearTimeout(timelineRangeTimer); timelineChart?.dispose(); window.removeEventListener('resize', resizeTimeline) })
</script>
